<?php $editing=!empty($tag);$typeLabels=['material'=>'Material','feature'=>'Característica','style'=>'Estilo','occasion'=>'Ocasião','commercial'=>'Comercial','audience'=>'Público','collection'=>'Coleção','administrative'=>'Administrativa']; ?>
<div class="dashboard-heading"><div><span class="eyebrow">TAGS</span><h2><?= $editing?'Editar tag':'Criar tag' ?></h2><p>Evite sinônimos e marque como administrativa qualquer tag que funcione como selo da plataforma.</p></div></div>
<form class="panel resource-form" method="post" action="<?= e($editing?url('/admin/tags/'.$tag['id']):url('/admin/tags')) ?>"><?= csrf_field() ?><?php if($editing):?><input type="hidden" name="_method" value="PUT"><?php endif;?><div class="form-grid"><label>Nome<input name="name" required value="<?= e($tag['name']??'') ?>"></label><label>Slug<input name="slug" value="<?= e($tag['slug']??'') ?>"></label><label>Tipo<select name="type"><?php foreach($types as $type):?><option value="<?= e($type) ?>" <?= ($tag['type']??'feature')===$type?'selected':'' ?>><?= e($typeLabels[$type]) ?></option><?php endforeach;?></select></label><label class="product-check"><input type="checkbox" name="is_admin_only" value="1" <?= !empty($tag['is_admin_only'])?'checked':'' ?>><span><strong>Uso exclusivo da administração</strong><small>Não aparece na seleção dos vendedores.</small></span></label><?php if($editing):?><label>Status<select name="status"><option value="active">Ativa</option><option value="inactive" <?= $tag['status']==='inactive'?'selected':'' ?>>Inativa</option></select></label><?php endif;?></div><div class="form-actions"><a class="button button--secondary" href="<?= e(url('/admin/tags')) ?>">Cancelar</a><button class="button button--primary">Salvar</button></div></form>
